        }
        window.addEventListener('resize', onWindowResize);
        init3DBackground();
        const chatView = document.getElementById('chat-view');
        const researchView = document.getElementById('research-view');
        const chatHistory = document.getElementById('chat-history');
        const messageForm = document.getElementById('message-form');
        const messageInput = document.getElementById('message-input');
        const sendButton = document.getElementById('send-button');
        const addButton = document.getElementById('add-button');
        const actionPopupMenu = document.getElementById('action-popup-menu');
        const menuResearch = document.getElementById('menu-research');
        const menuUpload = document.getElementById('menu-upload');
        const researchOptionsModalOverlay = document.getElementById('research-options-modal-overlay');
        const researchGoalSummary = document.getElementById('research-goal-summary');
        const submitResearchTask = document.getElementById('submit-research-task');
        const cancelResearchTask = document.getElementById('cancel-research-task');
        const toggleAdvancedOptions = document.getElementById('toggle-advanced-options');
        const advancedOptionsContainer = document.getElementById('advanced-options-container');
        const researchBackButton = document.getElementById('research-back-button');
        const researchTitle = document.getElementById('research-title');
        const researchContent = document.getElementById('research-content');
        const apiUrl = '/api/chat';
        const researchTasks = {};
        const activeIntervals = {};
        let activeTaskId = null;
        let currentMode = 'chat';
        let pendingResearchGoal = '';
        let isPopupVisible = false;
        let sessionId = localStorage.getItem('sessionId') || generateSessionId();
        let conversationHistory = [];
        function generateSessionId() {
            const id = 'session_' + Date.now() + '_' + Math.random().toString(36).substring(2, 9);
            localStorage.setItem('sessionId', id);
            return id;
        }
        async function loadChatHistory() {
            try {
                const response = await fetch(`/api/chat/history/${sessionId}`);
                if (response.ok) {
                    const data = await response.json();
                    conversationHistory = data.messages || [];
                    conversationHistory.forEach(msg => {
                        if (msg.role === 'user' || msg.role === 'assistant') {
                            addMessageToHistory(msg.content, msg.role === 'user' ? 'user' : 'ai', null, false, false);
                        }
                    });
                }
            } catch (error) {
                console.warn("Could not load chat history:", error);
            }
        }
        async function saveChatMessage(role, content) {
            try {
                await fetch(`/api/chat/history/${sessionId}`, {
                    method: 'POST',
                    headers: {'Content-Type': 'application/json'},
                    body: JSON.stringify({
                        message: {role, content}
                    })
                });
            } catch (error) {
                console.warn("Could not save chat message:", error);
            }
        }
        async function clearHistory() {
            try {
                await fetch(`/api/chat/history/${sessionId}`, {method: 'DELETE'});
                conversationHistory = [];
                chatHistory.innerHTML = '';
                sessionId = generateSessionId();
                addMessageToHistory("Előzmények törölve. Új beszélgetés kezdődik.", 'ai');
            } catch (error) {
                console.error("Error clearing history:", error);
                addMessageToHistory("Hiba történt az előzmények törlése közben.", 'ai', null, true);
            }
        }
        messageForm.addEventListener('submit', handleFormSubmit);
        messageInput.addEventListener('input', () => {
            sendButton.disabled = messageInput.value.trim().length === 0;
        });
        async function handleFormSubmit(e) {
            e.preventDefault();
            const prompt = messageInput.value.trim();
            if (!prompt) return;
            messageInput.value = '';
            sendButton.disabled = true;
            if (currentMode === 'chat') {
                await sendChatMessage(prompt);
            } else {
                openResearchOptionsSheet(prompt);
            }
        }
        async function sendChatMessage(prompt) {
            addMessageToHistory(prompt, 'user', null, false, true);
            addMessageToHistory(null, 'ai', 'typing-indicator');
            conversationHistory.push({role: 'user', content: prompt});
            await saveChatMessage('user', prompt);
            const contextWindow = conversationHistory.slice(-10);
            try {
                const response = await fetch(apiUrl, {
                    method: 'POST',
                    headers: {'Content-Type': 'application/json'},
                    body: JSON.stringify({
                        messages: contextWindow,
                        temperature: 0.7
                    })
                });
                if (!response.ok) {
                    const errorData = await response.json().catch(() => ({}));
                    throw new Error(errorData.error || `HTTP ${response.status}: ${response.statusText}`);
                }
                const result = await response.json();
                if (!result.choices || result.choices.length === 0) {
                    throw new Error('Nem érkezett válasz az AI modelltől');
                }
                const aiResponse = result.choices[0].message.content;
                if (!aiResponse || aiResponse.trim().length === 0) {
                    throw new Error('Üres válasz érkezett az AI modelltől');
                }
                conversationHistory.push({role: 'assistant', content: aiResponse});
                await saveChatMessage('assistant', aiResponse);
                updateMessageInHistory('typing-indicator', aiResponse, 'ai');
            } catch (error) {
                console.error("Hiba a Chat API hívásakor:", error);
                const errorMessage = `Hiba történt: ${error.message || 'Ismeretlen hiba'}. Kérem próbálja újra.`;
                updateMessageInHistory('typing-indicator', errorMessage, 'ai', true);
            }
        }
        function setChatMode(mode) {
            currentMode = mode;
            if (currentMode === 'chat') {
                messageInput.className = 'mode-chat';
                sendButton.className = 'mode-chat';
                messageInput.placeholder = 'Üzenet...';
