        submitResearchTask.addEventListener('click', async () => {
            const goal = pendingResearchGoal;
            if (!goal) return;
            const searchType = document.getElementById('search-type').value || 'auto';
            const category = document.getElementById('category').value || null;
            const userLocation = document.getElementById('user-location').value.trim() || null;
            const startDate = document.getElementById('start-date').value || null;
            const endDate = document.getElementById('end-date').value || null;
            const startCrawlDate = document.getElementById('start-crawl-date').value || null;
            const endCrawlDate = document.getElementById('end-crawl-date').value || null;
            const includeDomains = document.getElementById('include-domains').value.trim().split(',').map(d => d.trim()).filter(d => d);
            const excludeDomains = document.getElementById('exclude-domains').value.trim().split(',').map(d => d.trim()).filter(d => d);
            const includeText = document.getElementById('include-text').value.trim() || null;
            const excludeText = document.getElementById('exclude-text').value.trim() || null;
            const fullText = document.getElementById('full-text').checked;
            const aiSummary = document.getElementById('ai-summary').checked;
            const subpages = document.getElementById('subpages').checked;
            const subpageTarget = parseInt(document.getElementById('subpage-target').value) || 3;
            const livecrawl = document.getElementById('livecrawl').value || 'fallback';
            const livecrawlTimeout = document.getElementById('livecrawl-timeout').value || null;
            const links = document.getElementById('links').checked;
            hideResearchOptionsSheet();
            await startResearchTask(goal, {
                searchType,
                category,
                userLocation,
                startDate,
                endDate,
                startCrawlDate,
                endCrawlDate,
                includeDomains,
                excludeDomains,
                includeText,
                excludeText,
                fullText,
                aiSummary,
                subpages,
                subpageTarget,
                livecrawl,
                livecrawlTimeout,
                links
            });
        });
        async function startResearchTask(goal, options) {
            try {
                const payload = {
                    goal,
                    search_type: options.searchType,
                    category: options.category,
                    user_location: options.userLocation,
                    start_published_date: options.startDate,
                    end_published_date: options.endDate,
                    start_crawl_date: options.startCrawlDate,
                    end_crawl_date: options.endCrawlDate,
                    include_domains: options.includeDomains && options.includeDomains.length > 0 ? options.includeDomains : null,
                    exclude_domains: options.excludeDomains && options.excludeDomains.length > 0 ? options.excludeDomains : null,
                    include_text: options.includeText,
                    exclude_text: options.excludeText,
                    full_text: options.fullText,
                    ai_summary: options.aiSummary,
                    subpages: options.subpages,
                    subpage_target: options.subpageTarget,
                    livecrawl: options.livecrawl,
                    livecrawl_timeout: options.livecrawlTimeout,
                    links: options.links
                };
                const response = await fetch('/api/research/create', {
                    method: 'POST',
                    headers: {'Content-Type': 'application/json'},
                    body: JSON.stringify(payload)
                });
                if (!response.ok) throw new Error('Failed to create research task');
                const {task_id} = await response.json();
                researchTasks[task_id] = {id: task_id, goal, options, status: "Indítás...", progress: 0, subAgents: [], sources: [], report: ""};
                addResearchWidgetToHistory(task_id, goal, options);
                pollResearchStatus(task_id);
            } catch (error) {
                console.error("Error starting research:", error);
                addMessageToHistory("Hiba történt a kutatás indításakor.", 'ai', null, true);
            }
        }
        function pollResearchStatus(taskId) {
            if (activeIntervals[taskId]) {
                clearInterval(activeIntervals[taskId]);
            }
            const interval = setInterval(async () => {
                try {
